        while (l >= 0 && r < n && s[l] == s[r]) {
            --l;
            ++r;
        }
        int len = r - l - 1;
        int start = l + 1;
        if (len > bestLen || (len == bestLen && start < bestStart)) {
            bestLen = len;
            bestStart = start;
        }
    };

    for (int i = 0; i < n; ++i) {
        expand(i, i);
        expand(i, i + 1);
    }

