import sys


def solve() -> None:
    data = sys.stdin.read().split()
    if not data:
        return
    s = data[0]
    n = len(s)

    M1 = 1000000007
    M2 = 1000000009
    B1 = 311
    B2 = 317

    h1 = [0] * (n + 1)
    h2 = [0] * (n + 1)
    p1 = [1] * (n + 1)
    p2 = [1] * (n + 1)

    v1 = 0
    v2 = 0
    w1 = 1
    w2 = 1
    for i, ch in enumerate(s):
        c = ord(ch) - 96
        v1 = (v1 * B1 + c) % M1
        v2 = (v2 * B2 + c) % M2
        w1 = (w1 * B1) % M1
        w2 = (w2 * B2) % M2
        h1[i + 1] = v1
        h2[i + 1] = v2
        p1[i + 1] = w1
        p2[i + 1] = w2

    def has_dup(length: int) -> bool:
        if length == 0:
            return True
        pw1 = p1[length]
        pw2 = p2[length]
        seen = set()
        seen_add = seen.add
        for i in range(n - length + 1):
            x1 = (h1[i + length] - h1[i] * pw1) % M1
            x2 = (h2[i + length] - h2[i] * pw2) % M2
            key = (x1 << 30) | x2
            if key in seen:
                return True
            seen_add(key)
        return False

    lo, hi, ans = 0, n - 1, 0
    while lo <= hi:
        mid = (lo + hi) >> 1
        if has_dup(mid):
            ans = mid
            lo = mid + 1
        else:
            hi = mid - 1

    sys.stdout.write(f"{ans}\n")


